const classifications =
  JSON.parse(
    $input.first().json.message.content
  );

let rawSections =
  $('Webhook')
    .first()
    .json
    .body
    .resume_text;

// if string
if (
  typeof rawSections ===
  'string'
) {
  rawSections =
    JSON.parse(
      rawSections
    );
}

// if object containing sections
if (
  rawSections.sections
) {
  rawSections =
    rawSections.sections;
}

const mergedSections =
  classifications.sections
    .map(classification => {
      const section =
        rawSections.find(
          raw =>
            raw.title ===
            classification.originalTitle
        );

      return {
        originalTitle:
          classification.originalTitle,

        classifiedAs:
          classification.classifiedAs,

        content:
          section?.content || [],
      };
    })
    .filter(
      section =>
        section.classifiedAs !==
        'excluded'
    );

return [
  {
    json: {
      sections:
        mergedSections,
    },
  },
];

